        int q = sc.nextInt();
        char[] s = sc.next().toCharArray();

        int[] cnt = new int[n];
        for (int i = 1; i < n; i++) {
            if (s[i-1] == 'A' && s[i] == 'C') {
                cnt[i] = cnt[i-1] + 1;
            } else {
                cnt[i] = cnt[i-1];
