class Solver {
	Scanner sc;
	PrintWriter out;
    public Solver(InputStream in, PrintWriter out) {
    	sc = new Scanner(in);
    	this.out = out;
    }
    // ======================================================================
    public void solve() {
    	long A = nl();
    	long B = nl();
    	long C = nl();
    	int X = ni();
    	int Y = ni();
    	int max = Math.max(X,  Y);
    	int min = Math.min(X,  Y);
    	long ans = A * X + B * Y;
    	ans = Math.min(ans, C * min * 2 + A * (X - min) + B * (Y - min));
    	ans = Math.min(ans, C * max * 2);
    	out.println(ans);
    }
    // ------------------------------------------
    // 入力
    // ------------------------------------------
    public int ni() {
    	return sc.nextInt();
    }
    public long nl() {
    	return sc.nextLong();
    }
    public String ns() {
    	return sc.next();
    }
    public char[] nc() {
    	return sc.next().toCharArray();
    }
