	public static int prime(int n) {
		boolean check = false;
		int count = 0;
		int ans = 0;
		int j = 0;

		while(ans == 0) {
			ans = n+j;
			for(int i = 2; i < n + j -1; i++) {
				if((n+j)%i == 0) {
