class UF {
    private int[] id;
    private int[] size;
    private int count;
    public UF(int n) {
        id = new int[n];
        size = new int[n];
        count = n;
        for(int i = 0; i<n; ++i) {
            id[i] = i;
            size[i] = 1;
          }
    }
    public int countNum() {
        return count;
    }

    public boolean connected(int p, int q) {
        return find(p) == find(q);
    }

    public int find(int p) {
        while(p != id[p]) {
            id[p] = id[id[p]];
            p = id[p];
        }
        return p;
    }

    public void union(int p, int q) {
        int pRoot = find(p);
        int qRoot = find(q);
        if(pRoot == qRoot) return;
        if(size[qRoot] > size[pRoot]) {
          id[pRoot] = qRoot; 
          size[qRoot] += size[pRoot];
        } else {
          id[qRoot] = pRoot;
          size[pRoot] += size[qRoot];
        }
        --count;
    }
}
