class AtCoder {

    int s;

    AtCoder(FastScanner sc) {
        s = sc.nextInt();
    }

    void solve(PrintWriter out) {
        int a = s;
        int m = 0;
        for (int i = 1; i <= 1000000; i++) {
            if (a == 4 || a == 2 || a == 1) {
                m = i + 3;
                break;
            }
            a = func(a);
        }
        out.println(m);
    }

    int func(int n) {
        return n % 2 == 0 ? n / 2 : 3 * n + 1;
    }

}

