			if(search(nums,data[i])){
				ans++;
			}
		}
		System.out.println(ans);


	}
	public static boolean search(int[] nums,int x){
		int l =0; 
		int r = nums.length-1;
		while(l<=r){
			int mid = l+(r-l)/2;
			if(nums[mid]==x){
				return true;
			}else if(nums[mid]>x){
				r =mid-1;
			}else{
				l =mid+1;
			}
		}
		return false;
	}
}

