		public void solve(int testNumber, InputReader in, PrintWriter out) {

			char[] s = in.nextString().toCharArray();
			String[] t = new String[4];
			t[0] = ("dream");
			t[1] = ("dreamer");
			t[2] = ("erase");
			t[3] = ("eraser");

			int slen = s.length;
			while (slen > 0) {
				boolean isMatch = false;
				for (int k = 0; k < 4; k++) {
					int tlen = t[k].length();
					char[] tar = t[k].toCharArray();
