		long N=sc.nextLong();
		long K=sc.nextLong();
		long min=Long.MAX_VALUE;
		for (long i = -100; i < 100; i++) {
			min=Math.min(min, Math.abs(N-K*(i+(N/K))));
		}
		System.out.println(min);
