            for(int i=0; i < N; i++) {
                wk = in.nextDChar();
//                out.println("wk[0] = [" + wk[0] + "]  wk[" + wk.length 
//                        + "] = [" + wk[wk.length - 2] + "]  okFlag = " + okFlag);
            	sWk = new String(wk);
                if(i != 0) {
