        int cnt = 0;
        boolean ret = false;
        for (int i = 0; i < num.length; i++) {
            if (num[i] % 2 == 0) {
                cnt++;
            }
        }
        if (cnt == num.length) {
            ret = true;
        }
        return ret;
    }
}

