            int N = Integer.parseInt(br.readLine());
            List<String> inputNumberString = Arrays.asList(br.readLine().split(" "));
            List<Integer> numbers = new ArrayList<>();
            for (String str : inputNumberString) {
                numbers.add(Integer.parseInt(str));
            }

