                }
                if(val>min)
                    break;
                temp--;
            }
            temp=x;
            while(true){
                int val=temp-x;
                if(!set.contains(temp)&&val<min){
                    min=val;
                    num=temp;
                }
                if(val>min)
                    break;
                temp++;
            }
            sb.append(num).append('\n');
		}
		sb.deleteCharAt(sb.length()-1);
		out.println(sb);
	}

