    static class CMaximalValue {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int[] b = in.nextIntArray(n - 1);

            int[] a = new int[n];
            a[0] = b[0];
            a[n - 1] = b[n - 2];
            for (int i = 1; i <= n - 2; i++) {
