    static class BPolygon {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int max = 0, sum = 0;
            for (int i = 0; i < n; i++) {
                int s = in.nextInt();
                max = Math.max(max, s);
                sum += s;
            }

            boolean answer = (sum - max) > max;

            out.println(answer ? "Yes" : "No");
