	public static void main(String[] args) {

		// 1行目読み込む
		try {
			BufferedReader insBR = new BufferedReader(new InputStreamReader(
					System.in));

			String strNum = insBR.readLine();

			// 数値化
			int intNum = Integer.parseInt(strNum);

