            } else {
                map.put(str, 1);
            }
            if (max == map.get(str)) {
                list.add(str);
            } else if (max < map.get(str)) {
                list = new ArrayList<>();
                list.add(str);
            }
            max = Math.max(max, map.get(str));
        }
        String[] arr = list.toArray(new String[list.size()]);
        Arrays.sort(arr);

        String result = String.join("\r\n", arr);

        // 出力
        System.out.println(result);
        sc.close();
    }
}

