			array[i][1] = sc.nextInt();
			array[i][2] = sc.nextInt();
		}
		int x=0,y=0,t=0,i;
		for(i=0;i<n;i++) {
			int sub = array[i][0]-t;
			if((x+y)%2==0 ) {
				if(sub%2==0) {
					if((array[i][1]+array[i][2])%2!=0) break;
				}else {
					if((array[i][1]+array[i][2])%2==0) break;
				}
			}else {
				if(sub%2==0) {
					if((array[i][1]+array[i][2])%2==0) break;
				}else {
					if((array[i][1]+array[i][2])%2!=0) break;
				}
			}
			if(MHD(x,y,array[i][1],array[i][2])>sub) break;
			x=array[i][1];
			y=array[i][2];
			t=array[i][0];
		}
