            long aaabbb = bbb - aaa;

            long aaad = (a - 1) / d;
            long bbbd = b / d;
            long aaadbbbd = bbbd - aaad;

            long aaaf = (a - 1) / dd;
            long bbbf = b / dd;
            long aaafbbbf = bbbf - aaaf;

            out.printLine((b - a + 1) - (aaabbb + aaadbbbd - aaafbbbf));

