    static class BCollatzProblem {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            Set<Integer> h = new HashSet<>();
            int count = 2;
            h.add(n);
            boolean vaild = true;
            while (vaild) {
                if (n % 2 == 0) {
                    n /= 2;
                } else {
                    n = n * 3 + 1;
                }
                if (h.contains(n)) {
                    vaild = false;
                } else {
                    h.add(n);
                    count++;
                }

            }
            out.printLine(count);
        }

