    static class AFiveVariables {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int a[] = new int[5];
            int index = 0;
            for (int i = 0; i < 5; i++) {
                a[i] = in.nextInt();
                if (a[i] == 0)
                    index = i + 1;
            }
