        return a;
    }

    static int chmax(int a, int b) {
        if (a < b) {
            a = b;
            return a;
        }
        return a;
    }

    static int calcNumOfCombination(int n, int r) {
        int num = 1;
        for (int i = 1; i <= r; i++) {
            num = num * (n - i + 1) / i;
        }
        return num;
    }

    static long lcm(long a, long b) {
        long temp;
        long c = a;
        c *= b;
        while ((temp = a % b) != 0) {
            a = b;
            b = temp;
        }
        return (long) (c / b);
    }

    static long f(long n, Map<Long, Long> map) {
        if (n < 2)
            return 1;
        else if (map.containsKey(n)) {
            return map.get(n);
        } else {
            map.put(n, n * f(n - 2, map));
            return map.get(n);
        }

    }

    public long factorialUsingRecursion(int n) {
        if (n <= 2) {
            return n;
        }
        return n * factorialUsingRecursion(n - 1);
    }

    private static long calcLCM(long val1, long val2) {
        long maxValue = Math.max(val1, val2);
        long minValue = Math.min(val1, val2);
        long val3 = maxValue * minValue;

        if (minValue == 0)
            return maxValue;

        long temp;
        while ((temp = maxValue % minValue) != 0) {
            maxValue = minValue;
            minValue = temp;
        }

        return (long) (val3 / minValue);
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();
        Map<Integer, Integer> map = new HashMap<>();
        Map<Integer, Boolean> solved = new HashMap<>();
        int acCount = 0;
        int penalty = 0;
        for (int i = 0; i < m; i++) {
            int q = fs.nextInt();
            String judge = fs.next();

            if (judge.equals("WA")) {
                if (!solved.containsKey(q)) {
                    map.put(q, map.getOrDefault(q, 0) + 1);
                }
            } else {
                if (!solved.containsKey(q) || !solved.get(q)) {
                    penalty += map.getOrDefault(q,0);
                    acCount++;
                    solved.put(q, true);
                }
            }
        }

        System.out.print(acCount+" ");
        System.out.println(penalty);
    }

}

