static class ABC179B {

	public void solve(int testNum, FastInput in, PrintWriter out) {

		int n = in.nextInt();
		int [][]a = in.nextInt2DArray(n, 2);

		int []sum = new int [n+1];

		for(int i = 0 ; i < n ;i++) {
			if(a[i][0] == a[i][1]) {
				sum[i+1] = sum[i] + 1; 
			}
			else {
				sum[i+1] = 0;
			}
		}

		boolean f = false;

		for(int i = 1; i <= n ; i++) {
			if(sum[i] >= 3) {
				f = true;
			}
		}

		if(f){
			out.println("Yes");
		}
		else {
			out.println("No");
		}
	}

