		for(int i = 0 ; i < n ;i++) {
			res[i] = nextDouble();
		}
		return res;
	}


	public int[][] nextInt2DArray(final int n , final int m){
		int [][]res = new int [n][m];

		for(int i = 0 ; i < n ;i++) {
			for(int j = 0 ; j < m ;j++) {
				res[i][j] = nextInt();
			}
		}
		return res;
	}
	public long[][] nextLong2DArray(final int n , final int m){
		long [][]res = new long [n][m];

		for(int i = 0 ; i < n ;i++) {
			for(int j = 0 ; j < m ;j++) {
				res[i][j] = nextLong();
			}
		}
