			//i1つだけ足す
			result += (1 / Math.pow(2, pow)) ;

			// System.out.print(pow + " ");
			// System.out.println(result);
		}

		System.out.println(result/n);

	}

	// 2の何乗以下かを返す
	private static int calcPow(int n, int k) {
		for (int i = 0; i <= 18; i++) {
			if (n >= k) {
				return i;
			}
			n = n * 2;
		}
		return 0;
	}
}

