        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int k = in.nextInt();
            long ans = 0;
            for (int a = 1; a <= k; a++)
                for (int b = 1; b <= k; b++)
                    for (int c = 1; c <= k; c++)
                        ans += gcd(a, gcd(b, c));
            out.println(ans);
        }

        int gcd(int a, int b) {
            if (b == 0)
                return a;
            else
                return gcd(b, a % b);
        }

    }

