    Scanner scanner = new Scanner(System.in);
    String[] S = scanner.nextLine().split(" ");
    scanner.close();
    BigInteger N = new BigInteger(S[0]);
    BigInteger A = new BigInteger(S[1]);
    BigInteger B = new BigInteger(S[2]);
