		int sum = 0;
		for(int a = 1; a <= K; a++) {
			for(int b = 1; b <= K; b++) {
				for(int c = 1; c <= K; c++) {
					sum += gcd(a,b,c);
				}
			}
		}
		System.out.println(sum);


	}
	public static int gcd(int a, int b) {
		if(b == 0) return a;
		return gcd(b,a%b);
	}

	public static int gcd(int a, int b, int c) {
		return gcd(gcd(a,b),c);
	}

}

