    static class TaskA {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            String s = in.next();
            Hashtable<Character, Integer> table = new Hashtable<>();
            for (int i = 0; i < 4; i++) {
                char c = s.charAt(i);
                if (!table.containsKey(c))
                    table.put(c, 1);
                else {
                    int oldValue = table.get(c);
                    table.replace(c, oldValue + 1);
                }
