		ts = new TreeSet<>();
		permute("ABCDE".toCharArray(), 0);
		int[] a = new int[5];
		for(int i = 0; i < 5; i++) {
			a[i] = file.nextInt();
		}
		int ans = Integer.MAX_VALUE;
		for (String s : ts) {
			int time = 0;
			for (char c : s.toCharArray()) {
				if (time % 10 != 0) {
					time += 10 - time % 10;
				}
				time += a[c - 'A'];
			}
			ans = Math.min(ans, time);
		}
		System.out.println(ans);
	}

	void permute(char[] c, int x) {
		if (x == 5) {
			ts.add(String.valueOf(c));
		}
		else {
			for (int i = 0; i < 5; i++) {
				if (i != x) {
					char temp = c[i];
					c[i] = c[x];
					c[x] = temp;
					permute(c.clone(), x + 1);
					temp = c[i];
					c[i] = c[x];
					c[x] = temp;
				}
			}
		}
	}
	public static class FastIO {
		BufferedReader br;
		StringTokenizer st;

		public FastIO() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

