    static long modInverse(long a,long m) 
    { 
        long m0 = m; 
        long y = 0l, x = 1l; 

        if (m == 1) 
            return 0l; 

        while (a > 1) 
        { 

            long q = a / m; 

            long t = m; 

            m = a % m; 
            a = t; 
            t = y; 

            y = x - q * y; 
            x = t; 
        } 
        if (x < 0) 
            x += m0; 

        return x; 
    } 


