  private static int power2(int n, Map<Integer, Integer> memo) {
    Integer cached = memo.get(n);
    if (cached != null) {
      return cached;
    }

    if (n == 0) {
      return 1;
    }

    int tmp = power2(n/2, memo);
    int ret = tmp * tmp;
    if (n % 2 != 0) {
      ret = ret * 2;
    }
    memo.put(n, ret);

    return ret;
  }


  private static int powern(int a, int K) {

    int work = a;
    int ret = 0;

    while (work < K) {
      work = work * 2;
      ret++;
    }

    return ret;
  }
}

