public class Main {

	static PrintWriter out;
	static InputReader ir;
	static long[] f, fi;

	static void solve() {
		int n = ir.nextInt();
		int d = ir.nextInt();
		int[][] x = new int[n][];
		for (int i = 0; i < n; i++)
			x[i] = ir.nextIntArray(d);
		int res = 0;
		for (int i = 0; i < n; i++) {
			for (int j = i + 1; j < n; j++) {
				long a = 0;
				for (int k = 0; k < d; k++) {
					a += Math.pow(x[i][k] - x[j][k], 2);
				}
				long b = (long) Math.sqrt(a);
				if (b * b == a) {
					res++;
				}
			}
		}
		out.println(res);
	}

