  public static class Solver {
    public Solver() {

      long A = sc.nextLong();
      long B = sc.nextLong();
      long K = sc.nextLong();

      if (A >= K) {
        A -= K;
      } else {
        K -= A;
        A = 0;
        B = Math.max(0, B-K);
      }
      out.println(A + " " + B);

    }
  }

  public static void main(String[] args) {
