    public static void main(String[] args) {
        solve();
        out.flush();
    }

    private static void solve() {
        int n = in.nextInt();
        long ans = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= n; k++) {
                    ans += gcd(i, j, k);
                }
            }
        }
        out.println(ans);
    }

    static long gcd(long... a) {
        if (a.length == 0) return 1;
        long ret = a[0];
        for (int i = 1; i < a.length; i++) {
            ret = gcd(ret, a[i]);
        }
        return ret;
    }

    static long gcd(long a, long b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

