            }else{
                a = Math.abs(arr[i]-arr[i-1]) + soluteTopBottom(arr,i-1,ans);
            }

            if(ans[i-2]!=-1){
                b = Math.abs(arr[i]-arr[i-2]) + ans[i-2];
            }else{
                b = Math.abs(arr[i]-arr[i-2]) + soluteTopBottom(arr,i-2,ans);
            }

            return Math.min(a,b);
        }else if(i==1){
            ans[i] = Math.abs(arr[i] - arr[i-1]);
            return ans[i];
        }
        return -1;
