    static class Task {
        public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
            int n = in.nextInt();
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = in.nextLong();
            }
            long max = -1;
            long next = 0;
            for (int i = n-2; i >= 0; i--) {
                long count;
                if (arr[i] >= arr[i+1]){
                    count = next + 1;
                }else {
                    count = 0;
                }
                if (count > max){
                    max = count;
                }
                next = count;
            }
            out.println(Math.max(max, 0));
        }
    }

