			int children[][] = new int[2][length];
			int copyChildren[] = new int[length];
			for(int x = 0;x < length;x++){
				children[0][x] = 1;
				copyChildren[x] = children[0][x];
			}
			moveChildren(setRL,children,copyChildren,length);
