class Line{
    protected int[][] liner;
    protected int[] beq;
    protected int sum;
    public Line(int x,int y){
	liner=new int[x][];
	for(int i=0;i<x;i++) liner[i]=new int[y];
	beq=new int[y];
    }
    public void calc(int x,int y){
	for(int i=0;i<x;i++){
	    sum=0;
	    for(int j=0;j<y;j++){
		sum+=liner[i][j]*beq[j];
	    }
	    System.out.println(sum);
	}
    }
}

